Running command: cd /workspace && cat > test_jpeg_test.c << 'EOF'
#define STB_IMAGE_IMPLEMENTATION
#include "repo-vul/src-vul/stb/stb_image.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <image_file>\n", argv[0]);
        return 1;
    }

    // Read file
    FILE *f = fopen(argv[1], "rb");
    if (!f) { printf("Cannot open file\n"); return 1; }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char *buf = (unsigned char*)malloc(len);
    fread(buf, 1, len, f);
    fclose(f);

    // Test JPEG
    stbi__context s;
    stbi__start_mem(&s, buf, len);
    int r = stbi__jpeg_test(&s);
    printf("stbi__jpeg_test: %d\n", r);
    printf("Failure reason: %s\n", stbi_failure_reason());

    // Now try to load
    stbi__start_mem(&s, buf, len);
    int x, y, comp;
    unsigned char *img = stbi__jpeg_load(&s, &x, &y, &comp, 4, NULL);
    if (img) {
        printf("Loaded: %dx%d %d comp\n", x, y, comp);
        free(img);
    } else {
        printf("Load failed: %s\n", stbi_failure_reason());
    }

    free(buf);
    return 0;
}
EOF
gcc -g -o test_jpeg_test test_jpeg_test.c -lm 2>&1

